from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from datetime import datetime, timedelta
from typing import List, Optional

from ..database import get_db
from ..models import Container, Vessel, YardPosition, ContainerStatus
from ..schemas import ContainerIn, ContainerOut, valid_container_no

router = APIRouter(prefix="/api/containers", tags=["集装箱"])


def to_out(c: Container) -> dict:
    now = datetime.utcnow()
    days = (now - c.in_time).days if c.in_time and c.status == ContainerStatus.IN_YARD.value else None
    overdue = bool(c.in_time and c.status == ContainerStatus.IN_YARD.value
                   and now > c.in_time + timedelta(days=c.free_days))
    return {
        "id": c.id, "container_no": c.container_no, "size": c.size, "ctype": c.ctype,
        "status": c.status, "vessel_id": c.vessel_id, "position_id": c.position_id,
        "position_code": c.position.code if c.position else None,
        "vessel_name": c.vessel.vessel_name if c.vessel else None,
        "weight_t": c.weight_t, "consignee": c.consignee, "free_days": c.free_days,
        "in_time": c.in_time, "out_time": c.out_time, "has_hold": c.has_hold,
        "overdue": overdue, "days_in_yard": days,
    }


@router.get("", response_model=List[ContainerOut])
def list_containers(status: Optional[str] = None, q: Optional[str] = None,
                    db: Session = Depends(get_db)):
    query = db.query(Container)
    if status:
        query = query.filter(Container.status == status)
    if q:
        query = query.filter(Container.container_no.contains(q.upper()))
    return [to_out(c) for c in query.order_by(Container.id.desc()).all()]


@router.get("/overdue", response_model=List[ContainerOut])
def overdue_containers(db: Session = Depends(get_db)):
    """超期箱提醒: 在场且超过免堆存天数"""
    now = datetime.utcnow()
    containers = db.query(Container).filter(Container.status == ContainerStatus.IN_YARD.value).all()
    return [to_out(c) for c in containers
            if c.in_time and now > c.in_time + timedelta(days=c.free_days)]


@router.post("", response_model=ContainerOut)
def create_container(data: ContainerIn, db: Session = Depends(get_db)):
    no = data.container_no.upper()
    if not valid_container_no(no):
        raise HTTPException(400, "箱号格式错误，应为4位字母+7位数字 (ISO 6346)")
    if db.query(Container).filter(Container.container_no == no).first():
        raise HTTPException(409, "箱号已存在")
    if data.vessel_id and not db.get(Vessel, data.vessel_id):
        raise HTTPException(404, "船期不存在")
    c = Container(**{**data.model_dump(), "container_no": no})
    db.add(c)
    db.commit()
    db.refresh(c)
    return to_out(c)


@router.get("/{container_id}", response_model=ContainerOut)
def get_container(container_id: int, db: Session = Depends(get_db)):
    c = db.get(Container, container_id)
    if not c:
        raise HTTPException(404, "集装箱不存在")
    return to_out(c)


@router.patch("/{container_id}/hold", response_model=ContainerOut)
def toggle_hold(container_id: int, hold: bool = Query(...), db: Session = Depends(get_db)):
    c = db.get(Container, container_id)
    if not c:
        raise HTTPException(404, "集装箱不存在")
    c.has_hold = hold
    db.commit()
    db.refresh(c)
    return to_out(c)

import { useEffect, useState } from 'react'
import { api } from '../api'
import { fmt } from '../utils'

const STATUS = { BOOKED: '已预约', IN_YARD: '在场', OUT: '已出场' }

export default function Containers() {
  const [list, setList] = useState([])
  const [vessels, setVessels] = useState([])
  const [filter, setFilter] = useState({ status: '', q: '' })
  const [form, setForm] = useState({
    container_no: '', size: '40', ctype: 'GP', vessel_id: '',
    weight_t: '', consignee: '', free_days: 7,
  })
  const [msg, setMsg] = useState('')

  const load = () => {
    const p = new URLSearchParams()
    if (filter.status) p.set('status', filter.status)
    if (filter.q) p.set('q', filter.q)
    api.get('/containers?' + p).then(setList).catch((e) => setMsg(e.message))
  }
  useEffect(load, [filter])
  useEffect(() => { api.get('/vessels').then(setVessels) }, [])

  const submit = async (e) => {
    e.preventDefault()
    setMsg('')
    try {
      await api.post('/containers', {
        ...form,
        vessel_id: form.vessel_id ? Number(form.vessel_id) : null,
        weight_t: Number(form.weight_t) || 0,
        free_days: Number(form.free_days),
      })
      setForm({ ...form, container_no: '', weight_t: '', consignee: '' })
      setMsg('✅ 创建成功')
      load()
    } catch (err) { setMsg('❌ ' + err.message) }
  }

  const toggleHold = async (c) => {
    try {
      await api.patch(`/containers/${c.id}/hold?hold=${!c.has_hold}`)
      load()
    } catch (e) { alert(e.message) }
  }

  return (
    <div>
      <h2>集装箱管理</h2>
      <form className="panel form-row" onSubmit={submit}>
        <input placeholder="箱号 (如 MSKU1234567)" value={form.container_no}
          onChange={(e) => setForm({ ...form, container_no: e.target.value.toUpperCase() })}
          maxLength={11} required />
        <select value={form.size} onChange={(e) => setForm({ ...form, size: e.target.value })}>
          <option value="20">20尺</option><option value="40">40尺</option><option value="45">45尺</option>
        </select>
        <select value={form.ctype} onChange={(e) => setForm({ ...form, ctype: e.target.value })}>
          <option value="GP">普通箱</option><option value="HC">高箱</option><option value="RF">冷藏箱</option>
        </select>
        <select value={form.vessel_id} onChange={(e) => setForm({ ...form, vessel_id: e.target.value })}>
          <option value="">关联船期(可选)</option>
          {vessels.map((v) => <option key={v.id} value={v.id}>{v.vessel_name} / {v.voyage}</option>)}
        </select>
        <input placeholder="重量(吨)" type="number" step="0.1" value={form.weight_t}
          onChange={(e) => setForm({ ...form, weight_t: e.target.value })} />
        <input placeholder="货主" value={form.consignee}
          onChange={(e) => setForm({ ...form, consignee: e.target.value })} />
        <input placeholder="免堆天数" type="number" value={form.free_days}
          onChange={(e) => setForm({ ...form, free_days: e.target.value })} style={{ width: 90 }} />
        <button type="submit">登记箱</button>
      </form>
      {msg && <p className="msg">{msg}</p>}

      <div className="toolbar">
        <select value={filter.status} onChange={(e) => setFilter({ ...filter, status: e.target.value })}>
          <option value="">全部状态</option>
          <option value="BOOKED">已预约</option>
          <option value="IN_YARD">在场</option>
          <option value="OUT">已出场</option>
        </select>
        <input placeholder="搜索箱号…" value={filter.q}
          onChange={(e) => setFilter({ ...filter, q: e.target.value })} />
      </div>

      <table>
        <thead>
          <tr><th>箱号</th><th>尺寸/箱型</th><th>状态</th><th>船名/航次</th><th>堆位</th><th>货主</th><th>进场时间</th><th>在场天数</th><th>扣箱</th><th>操作</th></tr>
        </thead>
        <tbody>
          {list.map((c) => (
            <tr key={c.id} className={c.overdue ? 'row-red' : ''}>
              <td className="mono">{c.container_no}</td>
              <td>{c.size}'{c.ctype}</td>
              <td><span className={`tag s-${c.status}`}>{STATUS[c.status]}</span>
                {c.overdue && <span className="tag s-over">超期</span>}</td>
              <td>{c.vessel_name || '-'}</td>
              <td>{c.position_code || '-'}</td>
              <td>{c.consignee}</td>
              <td>{fmt(c.in_time)}</td>
              <td>{c.days_in_yard != null ? c.days_in_yard + ' 天' : '-'}</td>
              <td>{c.has_hold ? '🔒' : '-'}</td>
              <td>
                <button className="btn-sm" onClick={() => toggleHold(c)}>
                  {c.has_hold ? '解除扣箱' : '扣箱'}
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

